SELECT COUNT(*) AS matched, SUM(CASE WHEN p.amount IS DISTINCT FROM d.amount THEN 1 ELSE 0 END) AS differing, SUM(CASE WHEN d.amount IS NULL THEN 1 ELSE 0 END) AS dev_null FROM prod.orders p JOIN db.orders d ON p.id = d.id;
SELECT (SELECT COUNT(DISTINCT id) FROM db.orders) AS dev_distinct_ids, (SELECT COUNT(*) FROM db.orders) AS dev_rows, (SELECT COUNT(DISTINCT id) FROM prod.orders) AS prod_distinct_ids, (SELECT COUNT(*) FROM prod.orders p WHERE NOT EXISTS (SELECT 1 FROM db.orders d WHERE d.id=p.id)) AS prod_only;
SELECT p.id, p.amount AS prod_amount, d.amount AS dev_amount FROM prod.orders p JOIN db.orders d ON p.id=d.id WHERE p.amount IS DISTINCT FROM d.amount ORDER BY p.id LIMIT 20

